mapper.select:
SELECT oi.product_id AS productId, oi.product_name AS productName, SUM(oi.quantity) AS salesCount, COALESCE(SUM(oi.total_amount), 0) AS revenue FROM share_order.order_item oi JOIN share_order.order_info o ON oi.order_id = o.id AND o.del_flag = '0' WHERE oi.del_flag = '0' AND o.pay_status = '1'
AND o.create_time >= #{startDate}
AND o.create_time <= CONCAT(#{endDate}, ' 23:59:59')
GROUP BY oi.product_id, oi.product_name ORDER BY revenue salesCount DESC
LIMIT #{topN}

SELECT oi.merchant_id AS merchantId, COALESCE(mi.name, '未知商家') AS merchantName, COUNT(DISTINCT oi.order_id) AS orderCount, COALESCE(SUM(oi.total_amount), 0) AS revenue FROM share_order.order_item oi JOIN share_order.order_info o ON oi.order_id = o.id AND o.del_flag = '0' LEFT JOIN share_merchant.merchant_info mi ON oi.merchant_id = mi.id WHERE oi.del_flag = '0' AND o.pay_status = '1'
AND o.create_time >= #{startDate}
AND o.create_time <= CONCAT(#{endDate}, ' 23:59:59')
GROUP BY oi.merchant_id, mi.name ORDER BY revenue DESC
LIMIT #{topN}
